from bs4 import BeautifulSoup
from service.db import DB
from service.userAgent import user_agent_list
from service.nameMap import country_type_map, city_name_map, country_name_map, continent_name_map
import re
import json
import time
import random
import logging
import requests


class Crawler:
    def __init__(self):
        self.db = DB()
        self.user_agent_list = user_agent_list
        self.country_type_map = country_type_map
        self.city_name_map = city_name_map
        self.country_name_map = country_name_map
        self.continent_name_map = continent_name_map

    def run(self):
        self.crawler()

    def crawler(self):
        try:
            url = 'https://3g.dxy.cn/newh5/view/pneumonia'
            headers = {
                'User-Agent': random.choice(self.user_agent_list)
            }
            response = requests.get(url, headers=headers)
            soup = BeautifulSoup(response.content, 'lxml')
            overall = soup.find('script', id='getStatisticsService')
            province_list = soup.find('script', id='getListByCountryTypeService1')
            area_list = soup.find('script', id='getAreaStat')
            abroad_list = soup.find('script', id='getListByCountryTypeService2')
            news_list = soup.find('script', id='getTimelineService')
            rumor_list = soup.find('script', id='getRumorList')

            if overall:
                self.overall_parser(overall.text)
            if province_list:
                self.province_parser(province_list.text)
            if area_list:
                self.area_parser(area_list.text)
            if abroad_list:
                self.abroad_parser(abroad_list.text)
            if news_list:
                self.news_parser(news_list.text)
            if rumor_list:
                self.rumor_parser(rumor_list.text)
        except Exception as e:
            logging.error(f"Crawler error: {e}")

    def overall_parser(self, content):
        try:
            content = content.replace('try { getStatisticsService() } catch(e) {}', '').strip()
            data = json.loads(content)
            self.db.insert('overall', data)
        except Exception as e:
            logging.error(f"Overall parser error: {e}")

    def province_parser(self, content):
        try:
            content = content.replace('try { getListByCountryTypeService1() } catch(e) {}', '').strip()
            data = json.loads(content)
            for item in data:
                self.db.insert('province', item)
        except Exception as e:
            logging.error(f"Province parser error: {e}")

    def area_parser(self, content):
        try:
            content = content.replace('try { getAreaStat() } catch(e) {}', '').strip()
            data = json.loads(content)
            for item in data:
                self.db.insert('area', item)
        except Exception as e:
            logging.error(f"Area parser error: {e}")

    def abroad_parser(self, content):
        try:
            content = content.replace('try { getListByCountryTypeService2() } catch(e) {}', '').strip()
            data = json.loads(content)
            for item in data:
                self.db.insert('abroad', item)
        except Exception as e:
            logging.error(f"Abroad parser error: {e}")

    def news_parser(self, content):
        try:
            content = content.replace('try { getTimelineService() } catch(e) {}', '').strip()
            data = json.loads(content)
            for item in data:
                self.db.insert('news', item)
        except Exception as e:
            logging.error(f"News parser error: {e}")

    def rumor_parser(self, content):
        try:
            content = content.replace('try { getRumorList() } catch(e) {}', '').strip()
            data = json.loads(content)
            for item in data:
                self.db.insert('rumor', item)
        except Exception as e:
            logging.error(f"Rumor parser error: {e}")
